// Synthetic fixture builder (deterministic, seeded).
// case-synth-dominance : 3 questions (1000/50/30 answers) proving the
//                        big-question-dominance failure mode is detectable.
// case-synth-expert    : 1 question, 40 answers (10 low-vote experts + 30
//                        mainstream) proving expert-lane preservation.
// Fixture gold is FIXTURE_MECHANICAL (deterministic ground truth generated by
// the fixture spec, NOT human-adjudicated; scoring = FIXTURE_SANITY only).

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const ROOT = path.resolve('.');
const CORPUS = path.join(ROOT, 'benchmark/corpus');
const CASES = path.join(ROOT, 'benchmark/cases');

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(20260827);
const pick = (arr) => arr[Math.floor(rnd() * arr.length)];
const pickN = (arr, n) => { const out = []; const s = new Set(); while (out.length < n && s.size < arr.length) { const x = pick(arr); if (!s.has(x)) { s.add(x); out.push(x); } } return out; };
const ri = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));

function makeAnswer({ qid, id, author, voteupCount, createdTime, content, links = false }) {
  const a = {
    id: String(id), author, url: `https://www.zhihu.com/question/${qid}/answer/${id}`,
    content, voteupCount, commentCount: ri(0, 5), createdTime, updatedTime: createdTime,
  };
  if (links) {
    a.assets = { images: [], links: [{ originalUrl: 'https://example.com/ref', canonicalUrl: 'https://example.com/ref', domain: 'example.com', clickable: true, securityClass: 'external_unverified', zhihuRedirect: { targetUrl: 'https://example.com/ref', clickable: true }, anchorText: '参考' }], references: [], codeBlocks: [], videos: [] };
  } else {
    a.assets = { images: [], links: [], references: [], codeBlocks: [], videos: [] };
  }
  return a;
}

function writeQuestion({ qid, title, answerCount, fetchedAt, answers, verified = false }) {
  const j = {
    questionId: qid, questionTitle: title, answerCount, url: `https://www.zhihu.com/question/${qid}`,
    question: { id: qid, title, descriptionHtml: '', descriptionMarkdown: '', topics: [{ id: 'syn', name: 'synthetic' }] },
    fetchedAt, answers,
  };
  const buf = Buffer.from(JSON.stringify(j, null, 2), 'utf8');
  const dir = path.join(CORPUS, qid);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'answers.json'), buf);
  return { qid, title, answerCount, captured: answers.length, fetchedAt, sha256: crypto.createHash('sha256').update(buf).digest('hex'), bytes: buf.length, source: `synthetic-fixture:${qid}`, handoffVerified: verified };
}

